{
	"name": "opencode-fallback",
	"version": "1.2.0",
	"description": "OpenCode plugin that recovers from provider disconnects (resuming mid-response) and rate limits (switching to fallback model)",
	"type": "module",
	"main": "index.ts",
	"files": [
		"index.ts",
		"src"
	],
	"scripts": {
		"typecheck": "tsc --noEmit"
	},
	"keywords": [
		"opencode",
		"fallback",
		"disconnect",
		"resume",
		"recovery",
		"rate-limit",
		"model",
		"plugin"
	],
	"author": "liamjv1",
	"license": "MIT",
	"repository": {
		"type": "git",
		"url": "https://github.com/peva3/opencode-fallback.git"
	},
	"peerDependencies": {
		"@opencode-ai/plugin": ">=1.0.0"
	},
	"devDependencies": {
		"@opencode-ai/plugin": "^1.0.0",
		"@types/node": "^22.0.0",
		"typescript": "^5.0.0"
	}
}
